/* Portal da Cidade — painel do empresário */
'use strict';
function curCompany(){const mine=myCompanies();const c=mine.find(x=>x.id===S.curCid)||mine[0]||null;if(c&&S.curCid!==c.id){S.curCid=c.id;try{localStorage.setItem('pc_cid',c.id)}catch(e){}}return c}
const rawC=cid=>S.owners[S.uid]?.companies?.[cid];
const saveC=(cid,fn)=>mutateMy(b=>{b.companies=b.companies||{};const c=b.companies[cid];if(!c)throw new Error('Empresa não encontrada');fn(c,b);c.updatedAt=now()});
const PITEMS=[['painel','grid','Visão geral'],['painel-empresa','store','Minha empresa'],['painel-fotos','image','Fotos e galeria'],['painel-produtos','box','Produtos e serviços'],['painel-promocoes','tag','Promoções'],['painel-horarios','clock','Horário de funcionamento'],['painel-contatos','phone','Contatos e redes sociais'],['painel-localizacao','pin','Localização'],['painel-avaliacoes','star','Avaliações'],['painel-estatisticas','chart','Estatísticas'],['painel-eventos','cal','Eventos'],['painel-vagas','brief','Vagas de emprego'],['painel-plano','dollar','Meu plano'],['painel-config','cog','Configurações da conta']];
function painelLayout(html,key){const mine=myCompanies();const c=curCompany();return`<div class="dash"><nav class="side" aria-label="Painel do empresário"><div class="ttl">Painel do empresário</div>${mine.length>1?`<label class="sr" for="cidSwitch">Empresa ativa</label><select class="inp switcher" id="cidSwitch">${mine.map(m=>`<option value="${esc(m.id)}" ${m.id===c?.id?'selected':''}>${esc(m.name||'Sem nome')}</option>`).join('')}</select>`:c?`<div class="row" style="padding:6px 12px 10px;gap:10px">${logoEl(c,'avatar')}<b class="sm">${esc(c.name||'Sem nome')}</b></div>`:''}${PITEMS.map(([k,i,l])=>`<a href="#${k}" class="${key===k?'on':''}">${ic(i)}${l}</a>`).join('')}<div class="sep"></div><a href="#painel-nova" class="${key==='painel-nova'?'on':''}">${ic('plus')}Cadastrar outra empresa</a>${c?.pub?`<a href="#empresa-${esc(c.slug)}">${ic('eye')}Ver página pública</a>`:''}</nav><div class="dmain">${userBlocked(S.uid)?`<div class="note rd" style="margin-bottom:16px">${ic('alert')} Sua conta foi bloqueada pela administração. Suas empresas não aparecem no portal. Entre em contato com o administrador.</div>`:''}${html}</div></div>`}
document.addEventListener('change',e=>{if(e.target.id==='cidSwitch'){S.curCid=e.target.value;try{localStorage.setItem('pc_cid',S.curCid)}catch(x){}S.estep=1;render(false)}});
const noCompany=()=>`<div class="dhead"><div><h1>Cadastre sua primeira empresa</h1><p>Leva poucos minutos. Você preenche em etapas e pode salvar e continuar depois.</p></div></div><div class="card" style="max-width:640px"><ol class="sm" style="padding-left:18px"><li>Informações básicas e categoria</li><li>Contatos</li><li>Localização</li><li>Horário de funcionamento</li><li>Logomarca, capa e fotos</li><li>Revisão e envio para aprovação</li></ol><a class="btn btn-p" href="#painel-nova">${ic('plus','s')} Começar cadastro</a></div>`;
const pv=(key,o)=>Object.assign({auth:'profile',layout:'painel',key},o);

/* ---------- visão geral ---------- */
V.painel=pv('painel',{title:'Painel',render(){const c=curCompany();if(!c)return noCompany();const st=statsFor(c.id).tot;const cp=completeness(c);const plan=planById(c.plan);const promos=allPromos().filter(p=>p.companyId===c.id);const act=promos.filter(p=>p.status==='ativa').length;const m=c.m||{};const reason=(c.status==='rejeitado'||c.status==='suspenso')&&m.reason;
 return`<div class="dhead"><div class="row" style="gap:16px">${logoEl(c,'cp-logo','width:72px;height:72px;border-radius:18px;border-width:3px;font-size:24px')}<div><h1 style="margin:0 0 6px">${esc(c.name||'Sem nome')}</h1><div class="row">${statusChip(CSTATUS,c.status)}<span class="chip chip-gy">Plano ${esc(plan.name)}</span>${c.verified?`<span class="chip chip-gn">${ic('shield','s')}Verificada</span>`:''}${demoTag(c)}</div></div></div><div class="row"><a class="btn" href="#painel-empresa">${ic('edit','s')} Editar</a>${c.pub?`<a class="btn" href="#empresa-${esc(c.slug)}">${ic('eye','s')} Ver página pública</a>`:`<a class="btn" href="#empresa-${esc(c.slug)}">${ic('eye','s')} Pré-visualizar</a>`}<button class="btn btn-p" data-act="newPromo">${ic('tag','s')} Nova promoção</button></div></div>
 ${reason?`<div class="note rd" style="margin-bottom:16px">${ic('alert')} <span><b>${c.status==='rejeitado'?'Cadastro rejeitado':'Empresa suspensa'}:</b> ${esc(reason)}${c.status==='rejeitado'?' — ajuste as informações e envie novamente.':''}</span></div>`:''}
 ${c.status==='rascunho'||c.status==='rejeitado'?`<div class="note or" style="margin-bottom:16px">${ic('alert')} <span>Sua empresa ainda não está publicada. Complete as etapas e envie para aprovação. <a href="#painel-empresa" data-act="toStep" data-s="6">Ir para a revisão</a></span></div>`:c.status==='pendente'?`<div class="note" style="margin-bottom:16px">${ic('clock')} Cadastro enviado. A administração está analisando; você será publicado após a aprovação.</div>`:c.status==='revisao'?`<div class="note" style="margin-bottom:16px">${ic('clock')} Uma alteração sensível (nome ou categoria principal) está em análise. O público vê a versão aprovada.</div>`:''}
 <div class="kpis">${[['eye','Visualizações',st.v],['wa','Cliques no WhatsApp',st.w],['phone','Cliques no telefone',st.p],['route','Cliques em “Como chegar”',st.r],['tag','Promoções ativas',act]].map(([i,l,v])=>`<div class="kpi"><span>${ic(i,'s')}${l}</span><b>${nf(v)}</b></div>`).join('')}</div>
 <p class="xs muted" style="margin-top:-10px">Indicadores contam apenas interações reais de visitantes conectados (as suas não entram).</p>
 <div class="grid g2" style="margin-top:16px"><div class="card"><div class="row between"><h3 style="margin:0">Perfil ${cp.pct}% completo</h3></div><div class="progress" style="margin:12px 0"><i style="width:${cp.pct}%"></i></div><div class="list">${cp.items.filter(i=>!i[1]).map(i=>`<div class="row sm" style="gap:8px">${ic('alert','s')}${esc(i[0])}</div>`).join('')||`<div class="row sm" style="color:var(--vd)">${ic('check','s')} Tudo preenchido!</div>`}</div></div>
 <div class="card"><h3>Atalhos</h3><div class="grid g2" style="gap:8px">${[['painel-fotos','image','Gerenciar fotos'],['painel-produtos','box','Produtos e serviços'],['painel-horarios','clock','Horários'],['painel-promocoes','tag','Promoções'],['painel-estatisticas','chart','Estatísticas'],['painel-plano','dollar','Meu plano']].map(([k,i,l])=>`<a class="btn" href="#${k}" style="justify-content:flex-start">${ic(i,'s')}${l}</a>`).join('')}</div></div></div>`}});

/* ---------- assistente de cadastro / edição ---------- */
const STEPS=['Informações básicas','Contatos','Localização','Horário','Imagens','Revisão'];
ACT.toStep=a=>{S.estep=+a.dataset.s;if(S.route.n==='painel-empresa')render(false);else go('painel-empresa')};
function stepsBar(cur,c,isNew){return`<div class="steps" role="tablist">${STEPS.map((l,i)=>{const n=i+1;const ok=c&&[!!(c.name&&c.mainCat&&(c.description||'').length>=30),!!(c.contacts?.phone||c.contacts?.whatsapp),!!(c.loc?.zone&&c.loc?.bairro),!!c.hours?.week,!!(c.logo||c.cover),!!c.submittedAt][i];return`<a href="#painel-empresa" ${isNew&&n>1?'aria-disabled="true"':`data-act="toStep" data-s="${n}"`} class="${n===cur?'on':''} ${ok?'ok':''}" role="tab" aria-selected="${n===cur}"><b>${ok&&n!==cur?'✓':n}</b>${l}</a>`}).join('')}</div>`}
function editor(step,{isNew=false}={}){const c=isNew?null:curCompany();if(!isNew&&!c)return noCompany();const r=isNew?{}:rawC(c.id)||{};const head=`<div class="dhead"><div><h1>${isNew?'Cadastrar empresa':'Minha empresa'}</h1><p>${isNew?'Etapa 1 de 6 — salve para continuar com as próximas etapas.':`${statusChip(CSTATUS,c.status)} &nbsp;As alterações são salvas a cada etapa.`}</p></div>${!isNew?`<a class="btn" href="#empresa-${esc(c.slug)}">${ic('eye','s')} ${c.pub?'Ver página':'Pré-visualizar'}</a>`:''}</div>`+stepsBar(step,isNew?null:r,isNew);
 const nav=(back=true)=>`<div class="row between" style="margin-top:6px">${back&&step>1?`<button type="button" class="btn" data-act="toStep" data-s="${step-1}">${ic('left','s')} Voltar</button>`:'<span></span>'}<button class="btn btn-p">Salvar e continuar ${ic('right','s')}</button></div>`;
 if(step===1){const me=S.me||{};const doc=me.docs?.[c?.id]||'';const mc=r.mainCat||'';return head+`<form class="card" data-form="step1" novalidate ${isNew?'data-new="1"':''}><div class="fgrid"><div class="fld full"><label for="s1n">Nome fantasia *</label><input id="s1n" type="text" name="name" value="${esc(r.name||'')}" required maxlength="80"></div><div class="fld"><label for="s1pt">Perfil</label><select id="s1pt" name="personType"><option value="pj" ${r.personType!=='pf'?'selected':''}>Empresa (CNPJ)</option><option value="pf" ${r.personType==='pf'?'selected':''}>Profissional autônomo (CPF)</option></select></div><div class="fld"><label for="s1doc">CNPJ ou CPF</label><input id="s1doc" type="text" name="doc" value="${esc(doc)}" data-mask="doc" inputmode="numeric"><span class="hint">Opcional. Usado só para verificação; não é exibido publicamente.</span></div><div class="fld full"><label for="s1rs">Razão social</label><input id="s1rs" type="text" name="legalName" value="${esc(r.legalName||'')}"><span class="hint">Opcional, conforme o perfil.</span></div><div class="fld full"><label for="s1d">Descrição da empresa *</label><textarea id="s1d" name="description" maxlength="1500" required>${esc(r.description||'')}</textarea><span class="hint">Mínimo de 30 caracteres. Conte o que você oferece e o seu diferencial.</span></div><div class="fld"><label for="s1f">Ano de fundação</label><input id="s1f" type="number" name="founded" min="1800" max="${new Date().getFullYear()}" value="${esc(r.founded||'')}"></div><div class="fld"><label for="s1e">Tipo de estabelecimento *</label><select id="s1e" name="estab" required>${Object.entries(ESTAB).map(([k,l])=>`<option value="${k}" ${r.estab===k?'selected':''}>${l}</option>`).join('')}</select></div><div class="fld full"><label for="s1c">Categoria principal *</label><select id="s1c" name="mainCat" required><option value="">Selecione</option>${mainCats().map(x=>`<option value="${esc(x.id)}" ${mc===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>${c?.pub?'<span class="hint">Alterar a categoria principal ou o nome exige nova aprovação.</span>':''}</div><div class="fld full"><span class="lbl2">Subcategorias</span><div class="checks" id="subBox">${subChecks(mc,r.subs||[])}</div></div><div class="fld full"><span class="lbl2">Também atua em (categorias adicionais)</span><div class="checks">${mainCats().filter(x=>x.id!==mc).map(x=>`<label class="chk"><input type="checkbox" name="extraCats[]" value="${esc(x.id)}" ${(r.extraCats||[]).includes(x.id)?'checked':''}>${esc(x.name)}</label>`).join('')}</div></div><div class="fld full"><label for="s1k">Palavras-chave</label><input id="s1k" type="text" name="keywords" value="${esc(r.keywords||'')}" placeholder="Ex.: pão francês, bolo de festa, café da manhã"><span class="hint">Separe por vírgulas. Ajuda as pessoas a encontrarem você na busca.</span></div></div>${nav()}</form>`}
 if(step===2){const ct=r.contacts||{};return head+`<form class="card" data-form="step2" novalidate><div class="fgrid"><div class="fld"><label for="s2p">Telefone</label><input id="s2p" type="tel" name="phone" value="${esc(ct.phone||'')}" data-mask="phone"></div><div class="fld"><label for="s2w">WhatsApp</label><input id="s2w" type="tel" name="whatsapp" value="${esc(ct.whatsapp||'')}" data-mask="phone"></div><div class="fld full"><span class="hint">Informe pelo menos telefone ou WhatsApp.</span></div><div class="fld"><label for="s2e">E-mail comercial</label><input id="s2e" type="email" name="email" value="${esc(ct.email||'')}"></div><div class="fld"><label for="s2i">Instagram</label><input id="s2i" type="text" name="instagram" value="${esc(ct.instagram||'')}" placeholder="@suaempresa"></div><div class="fld"><label for="s2f">Facebook</label><input id="s2f" type="text" name="facebook" value="${esc(ct.facebook||'')}" placeholder="facebook.com/suaempresa"></div><div class="fld"><label for="s2s">Site oficial</label><input id="s2s" type="url" name="site" value="${esc(ct.site||'')}" placeholder="https://"></div><div class="fld full"><label for="s2c">Link de catálogo</label><input id="s2c" type="url" name="catalog" value="${esc(ct.catalog||'')}" placeholder="https://"></div></div>${nav()}</form>`}
 if(step===3){const l=r.loc||{};const z=l.zone||'';return head+`<form class="card" data-form="step3" novalidate><div class="fgrid"><div class="fld"><label for="s3c">Cidade</label><input id="s3c" type="text" name="city" value="${esc(l.city||site().city)}"></div><div class="fld"><label for="s3cep">CEP</label><input id="s3cep" type="text" name="cep" value="${esc(l.cep||'')}" data-mask="cep" inputmode="numeric"></div><div class="fld"><label for="s3z">Zona *</label><select id="s3z" name="zone" required><option value="">Selecione</option>${zones().map(x=>`<option value="${esc(x.id)}" ${z===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="fld"><label for="s3b">Bairro *</label><select id="s3b" name="bairro" required><option value="">Selecione a zona primeiro</option>${(zoneById(z)?.bairros||[]).map(b=>`<option value="${esc(b.id)}" ${l.bairro===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div><div class="fld full"><label class="chk"><input type="checkbox" name="hideAddress" ${l.hideAddress?'checked':''}> Ocultar endereço público (para quem atende em domicílio)</label></div><div class="fld full"><label for="s3r">Rua</label><input id="s3r" type="text" name="street" value="${esc(l.street||'')}"></div><div class="fld"><label for="s3n">Número</label><input id="s3n" type="text" name="number" value="${esc(l.number||'')}"></div><div class="fld"><label for="s3co">Complemento</label><input id="s3co" type="text" name="complement" value="${esc(l.complement||'')}"></div><div class="fld full"><label for="s3m">Localização no mapa</label><input id="s3m" type="text" name="coords" value="${l.lat?esc(l.lat+', '+l.lng):''}" placeholder="Cole um link do Google Maps ou as coordenadas (ex.: -5.79, -35.20)"><span class="hint">No Google Maps, toque e segure no local, copie as coordenadas e cole aqui. Usado no botão “Como chegar”.</span></div><div class="fld full"><label for="s3a">Área de atendimento</label><input id="s3a" type="text" name="area" value="${esc(l.area||'')}" placeholder="Ex.: toda a zona Sul e Centro"></div></div>${nav()}</form>`}
 if(step===4){const h=r.hours||{};const w=h.week||{};return head+`<form class="card" data-form="step4"><div class="row between" style="margin-bottom:10px"><h3 style="margin:0">Semana</h3><button type="button" class="btn btn-sm" data-act="copyMon">Copiar segunda para seg–sex</button></div><div class="tblw"><table class="tbl"><thead><tr><th>Dia</th><th>Fechado</th><th>Abre</th><th>Fecha</th><th>Intervalo início</th><th>Intervalo fim</th></tr></thead><tbody>${WEEK.map(d=>{const x=w[d]||(h.week?{closed:true}:{open:d==='dom'?'':'08:00',close:d==='dom'?'':'18:00',closed:d==='dom'});return`<tr data-day="${d}"><td><b>${DAYL[d]}</b></td><td><input type="checkbox" name="${d}_closed" ${x.closed?'checked':''} aria-label="${DAYL[d]} fechado" style="width:20px;height:20px"></td>${['open','close','breakStart','breakEnd'].map(k=>`<td><input class="inp" type="time" name="${d}_${k}" value="${esc(x[k]||'')}" aria-label="${DAYL[d]} ${k}" style="min-width:110px"></td>`).join('')}</tr>`}).join('')}</tbody></table></div>
 <h3 style="margin-top:22px">Horários especiais e dias fechados</h3><p class="sm muted">Feriados, datas comemorativas ou dias em que não vai abrir.</p><div id="spList">${(h.special||[]).map(spRow).join('')}</div><button type="button" class="btn btn-sm" data-act="addSp">${ic('plus','s')} Adicionar data</button><div class="fld" style="margin-top:16px"><label for="s4n">Observações</label><input id="s4n" type="text" name="notes" value="${esc(h.notes||'')}" placeholder="Ex.: delivery até 23h"></div>${nav()}</form>`}
 if(step===5){return head+`<div class="card"><h3>Logomarca e capa</h3><div class="grid g2"><div><p class="sm muted">Logomarca (quadrada, mínimo 300×300)</p><div class="row">${logoEl({...r,pubName:r.name,pubCat:r.mainCat},'cp-logo','width:96px;height:96px;border-radius:20px;border-width:2px;font-size:30px')}<div class="list"><label class="btn btn-sm">${ic('upload','s')} ${r.logo?'Trocar':'Enviar'} logomarca<input type="file" accept="image/jpeg,image/png,image/webp" class="sr" data-up="logo"></label>${r.logo?`<button class="btn btn-sm btn-dl" data-act="rmImg" data-k="logo">${ic('trash','s')} Remover</button>`:''}</div></div></div><div><p class="sm muted">Imagem de capa (horizontal, ideal 1600×600)</p><div style="height:110px;border-radius:14px;${coverStyle({...r,pubCat:r.mainCat})};background-size:cover;background-position:center;margin-bottom:8px"></div><div class="row"><label class="btn btn-sm">${ic('upload','s')} ${r.cover?'Trocar':'Enviar'} capa<input type="file" accept="image/jpeg,image/png,image/webp" class="sr" data-up="cover"></label>${r.cover?`<button class="btn btn-sm btn-dl" data-act="rmImg" data-k="cover">${ic('trash','s')} Remover</button>`:''}</div></div></div><p class="xs muted" style="margin-top:10px">As imagens são compactadas e convertidas para WebP automaticamente. Formatos aceitos: JPG, PNG e WebP até 10 MB.</p></div><div class="card"><h3>Galeria de fotos</h3><div id="galBox">${galleryBlock(c)}</div></div><div class="row between" style="margin-top:16px"><button class="btn" data-act="toStep" data-s="4">${ic('left','s')} Voltar</button><button class="btn btn-p" data-act="toStep" data-s="6">Continuar para revisão ${ic('right','s')}</button></div>`}
 if(step===6){const miss=submitMissing(r);const blocked=userBlocked(S.uid);return head+`<div class="card"><div class="row between"><h3 style="margin:0">Prévia da página da empresa</h3><span class="sm muted">É assim que o público verá</span></div><div style="border:1px solid var(--line);border-radius:16px;overflow:hidden;margin-top:14px;max-height:620px;overflow-y:auto">${companyPage({...c,...r,id:c.id,contacts:r.contacts,loc:r.loc},{draft:true,preview:true})}</div></div><div class="card">${miss.length?`<div class="note or">${ic('alert')} <span>Antes de enviar, complete: ${miss.map(esc).join(', ')}.</span></div>`:c.status==='pendente'?`<div class="note">${ic('clock')} Seu cadastro já está em análise. Se fizer alterações, ele continua na fila.</div>`:c.status==='aprovado'?`<div class="note vd">${ic('check')} Sua empresa está aprovada e publicada.</div>`:c.status==='suspenso'?`<div class="note rd">${ic('alert')} Empresa suspensa pela administração.</div>`:''}<div class="row" style="margin-top:14px"><button class="btn btn-p" data-act="submitC" ${miss.length||blocked||c.status==='pendente'||c.status==='aprovado'||c.status==='revisao'||c.status==='suspenso'?'disabled':''}>${ic('check','s')} Enviar empresa para aprovação</button><button class="btn" data-act="toStep" data-s="1">Editar informações</button></div></div>`}
 return head}
function subChecks(mc,sel){const s=subCats(mc);return s.length?s.map(x=>`<label class="chk"><input type="checkbox" name="subs[]" value="${esc(x.id)}" ${sel.includes(x.id)?'checked':''}>${esc(x.name)}</label>`).join(''):'<span class="sm muted">Escolha a categoria principal para ver as subcategorias.</span>'}
function spRow(s={}){return`<div class="row sp" style="margin-bottom:8px;align-items:flex-end"><input class="inp" type="date" name="sp_date[]" value="${esc(s.date||'')}" aria-label="Data" style="width:auto"><input class="inp" type="text" name="sp_label[]" value="${esc(s.label||'')}" placeholder="Motivo (ex.: Natal)" aria-label="Motivo" style="flex:1;min-width:140px"><input class="inp" type="time" name="sp_open[]" value="${esc(s.open||'')}" aria-label="Abre" style="width:auto"><input class="inp" type="time" name="sp_close[]" value="${esc(s.close||'')}" aria-label="Fecha" style="width:auto"><select class="inp" name="sp_closed[]" aria-label="Situação" style="width:auto"><option value="0">Aberto</option><option value="1" ${s.closed?'selected':''}>Fechado</option></select><button type="button" class="btn btn-sm btn-g" data-act="rmSp" aria-label="Remover data">${ic('trash','s')}</button></div>`}
ACT.addSp=()=>$('#spList').insertAdjacentHTML('beforeend',spRow());ACT.rmSp=a=>a.closest('.sp').remove();
ACT.copyMon=()=>{const g=k=>$(`[name="seg_${k}"]`).value;['ter','qua','qui','sex'].forEach(d=>{['open','close','breakStart','breakEnd'].forEach(k=>$(`[name="${d}_${k}"]`).value=g(k));$(`[name="${d}_closed"]`).checked=$('[name="seg_closed"]').checked});toast('Horário de segunda copiado para terça a sexta.')};
function submitMissing(r){const m=[];if(!r.name)m.push('nome');if((r.description||'').length<30)m.push('descrição');if(!r.mainCat)m.push('categoria principal');if(!(r.contacts?.phone||r.contacts?.whatsapp))m.push('telefone ou WhatsApp');if(!r.loc?.zone||!r.loc?.bairro)m.push('zona e bairro');if(!r.loc?.hideAddress&&!r.loc?.street)m.push('rua (ou marque ocultar endereço)');return m}
document.addEventListener('change',e=>{if(e.target.id==='s1c'){const b=$('#subBox');if(b)b.innerHTML=subChecks(e.target.value,[])}if(e.target.id==='s3z'){const b=$('#s3b');if(b)b.innerHTML='<option value="">Selecione</option>'+(zoneById(e.target.value)?.bairros||[]).map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}});
['painel-empresa','painel-contatos','painel-localizacao','painel-horarios'].forEach((k,i)=>{V[k]=pv(k,{title:'Minha empresa',live:false,render(){const st=k==='painel-empresa'?(S.estep||1):[0,2,3,4][i];return editor(st)},after(){bindUploads();bindGallery()}})});
V['painel-nova']=pv('painel-nova',{title:'Cadastrar empresa',live:false,render(){return editor(1,{isNew:true})}});
function uniqueSlug(name,cid){let base=slugify(name),s=base,i=2;while(allCompanies().some(c=>c.slug===s&&c.id!==cid))s=base+'-'+(i++);return s}
FORM.step1=async(f,o)=>{clearErr(f);let bad=false;if(o.name.length<2){fieldErr(f,'name','Informe o nome fantasia.');bad=true}if((o.description||'').length<30){fieldErr(f,'description','Mínimo de 30 caracteres.');bad=true}if(!o.mainCat){fieldErr(f,'mainCat','Selecione a categoria principal.');bad=true}const d=digits(o.doc);if(d&&!(d.length===11?validCPF(d):d.length===14?validCNPJ(d):false)){fieldErr(f,'doc','CPF ou CNPJ inválido.');bad=true}if(o.founded&&(+o.founded<1800||+o.founded>new Date().getFullYear())){fieldErr(f,'founded','Ano inválido.');bad=true}if(bad)return toast('Revise os campos destacados.','err');
 const isNew=!!f.dataset.new;const cid=isNew?genId():curCompany().id;const prev=compById(cid);let sensitive=false;
 const ok=await W(mutateMy(b=>{b.companies=b.companies||{};b.promos=b.promos||{};b.events=b.events||{};b.jobs=b.jobs||{};const c=b.companies[cid]||(b.companies[cid]={createdAt:now(),slug:uniqueSlug(o.name,cid)});Object.assign(c,{name:o.name,legalName:o.legalName,personType:o.personType,description:o.description,founded:o.founded,estab:o.estab,mainCat:o.mainCat,subs:o.subs||[],extraCats:(o.extraCats||[]).filter(x=>x!==o.mainCat),keywords:o.keywords,updatedAt:now()});const snap=prev?.m?.snapshot;if(prev&&prev.m?.status==='aprovado'&&snap&&(snap.name!==o.name||snap.mainCat!==o.mainCat)){c.submittedAt=now();sensitive=true}}));
 if(!ok)return;if(d||S.me?.docs?.[cid])await W(mutatePriv(b=>{b.docs=b.docs||{};if(d)b.docs[cid]=o.doc;else delete b.docs[cid]}));
 if(sensitive)toast('Alteração sensível enviada para nova aprovação. O público vê a versão aprovada até lá.');else toast('Informações salvas.','ok');
 S.curCid=cid;try{localStorage.setItem('pc_cid',cid)}catch(e){}S.estep=2;go('painel-empresa')};
FORM.step2=async(f,o)=>{clearErr(f);if(digits(o.phone).length<10&&digits(o.whatsapp).length<10){fieldErr(f,'phone','Informe telefone ou WhatsApp com DDD.');return}if(o.email&&!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(o.email)){fieldErr(f,'email','E-mail inválido.');return}for(const k of['site','catalog'])if(o[k]&&!safeUrl(o[k])){fieldErr(f,k,'Link inválido.');return}const cid=curCompany().id;if(await W(saveC(cid,c=>{c.contacts={phone:o.phone,whatsapp:o.whatsapp,email:o.email,instagram:o.instagram,facebook:o.facebook,site:o.site?safeUrl(o.site):'',catalog:o.catalog?safeUrl(o.catalog):''}}),'Contatos salvos.')){S.estep=3;go('painel-empresa')}};
function parseCoords(s){s=String(s||'');const m=s.match(/@(-?\d+\.\d+),(-?\d+\.\d+)/)||s.match(/(-?\d{1,3}\.\d+)\s*,\s*(-?\d{1,3}\.\d+)/)||s.match(/[?&](?:q|query|destination)=(-?\d+\.\d+)(?:,|%2C)(-?\d+\.\d+)/);if(!m)return null;const lat=+m[1],lng=+m[2];if(Math.abs(lat)>90||Math.abs(lng)>180)return null;return{lat,lng}}
FORM.step3=async(f,o)=>{clearErr(f);let bad=false;if(!o.zone){fieldErr(f,'zone','Selecione a zona.');bad=true}if(!o.bairro){fieldErr(f,'bairro','Selecione o bairro.');bad=true}if(!o.hideAddress&&!o.street){fieldErr(f,'street','Informe a rua ou marque “ocultar endereço”.');bad=true}if(o.cep&&digits(o.cep).length!==8){fieldErr(f,'cep','CEP deve ter 8 dígitos.');bad=true}const co=o.coords?parseCoords(o.coords):null;if(o.coords&&!co){fieldErr(f,'coords','Não reconhecemos as coordenadas.');bad=true}if(bad)return;const cid=curCompany().id;if(await W(saveC(cid,c=>{c.loc={city:o.city,cep:o.cep,zone:o.zone,bairro:o.bairro,hideAddress:o.hideAddress,street:o.street,number:o.number,complement:o.complement,area:o.area,lat:co?.lat||null,lng:co?.lng||null}}),'Localização salva.')){S.estep=4;go('painel-empresa')}};
FORM.step4=async(f,o)=>{const week={};for(const d of WEEK){const x={closed:!!o[d+'_closed'],open:o[d+'_open'],close:o[d+'_close'],breakStart:o[d+'_breakStart'],breakEnd:o[d+'_breakEnd']};if(!x.closed&&(!x.open||!x.close)){toast(`Informe abertura e fechamento de ${DAYL[d]} ou marque como fechado.`,'err');return}if(!!x.breakStart!==!!x.breakEnd){toast(`Intervalo de ${DAYL[d]}: informe início e fim.`,'err');return}week[d]=x}const sp=(o.sp_date||[]).map((dt,i)=>({date:dt,label:o.sp_label[i],open:o.sp_open[i],close:o.sp_close[i],closed:o.sp_closed[i]==='1'})).filter(x=>x.date);const cid=curCompany().id;if(await W(saveC(cid,c=>{c.hours={week,special:sp,notes:o.notes}}),'Horários salvos.')){S.estep=5;go('painel-empresa')}};
ACT.submitC=async()=>{const c=curCompany();const miss=submitMissing(rawC(c.id));if(miss.length)return toast('Complete: '+miss.join(', '),'err');if(!await confirmBox('Enviar sua empresa para análise da administração? Você poderá continuar editando enquanto isso.',{ok:'Enviar para aprovação'}))return;if(await W(saveC(c.id,x=>{x.submittedAt=now()}),'Enviado! Acompanhe o status pelo painel.'))go('painel')};

/* ---------- imagens: logo, capa e galeria ---------- */
function bindUploads(){$$('input[type=file][data-up]').forEach(inp=>inp.onchange=async()=>{const file=inp.files[0];if(!file)return;const k=inp.dataset.up;const c=curCompany();toast('Enviando imagem…');try{const old=rawC(c.id)?.[k];const img=await uploadImage(file,k==='logo'?{max:512,q:.85,inline:true,inlineMax:200}:{max:1800,q:.8});if(await W(saveC(c.id,x=>{x[k]=img}),k==='logo'?'Logomarca atualizada.':'Capa atualizada.')){deleteAsset(old);render(false)}}catch(e){toast(e.message,'err')}})}
ACT.rmImg=async a=>{const k=a.dataset.k;if(!await confirmBox(`Remover a ${k==='logo'?'logomarca':'imagem de capa'}?`,{ok:'Remover',danger:true}))return;const c=curCompany();const old=rawC(c.id)?.[k];if(await W(saveC(c.id,x=>{delete x[k]}),'Imagem removida.')){deleteAsset(old);render(false)}};
S.pend=[];
function galleryBlock(c){const r=rawC(c.id)||{};const g=r.gallery||[];const lim=planById(c.plan).photos||5;const left=lim-g.length-S.pend.length;return`<div class="row between" style="margin-bottom:10px"><span class="sm muted">${nf(g.length)} de ${nf(lim)} fotos do plano ${esc(planById(c.plan).name)}</span>${left<=0?'<a class="sm" href="#painel-plano">Aumentar limite</a>':''}</div><div class="drop" id="dropZone" data-act="pickImgs" role="button" tabindex="0" aria-label="Adicionar fotos">${ic('upload','l')}<p style="margin:8px 0 2px"><b>Arraste e solte as fotos aqui</b> ou toque para escolher</p><span class="xs muted">JPG, PNG ou WebP até 10 MB · compactação automática</span><input type="file" id="galInput" accept="image/jpeg,image/png,image/webp" multiple class="sr"></div>
 ${S.pend.length?`<div class="card" style="margin-top:14px;background:#fcfbf8"><div class="row between"><b>Pré-visualização (${S.pend.length}) — ainda não publicadas</b><div class="row"><button class="btn btn-sm btn-g" data-act="clearPend">Descartar</button><button class="btn btn-sm btn-p" data-act="pubPend">${ic('upload','s')} Publicar fotos</button></div></div><div class="gal">${S.pend.map((p,i)=>`<div class="gi"><img src="${p.url}" alt="Pré-visualização"><div class="gb"><input placeholder="Legenda" value="${esc(p.caption)}" data-pc="${i}" aria-label="Legenda"><select class="inp" style="min-height:32px;padding:4px 8px;font-size:13px" data-pk="${i}" aria-label="Tipo"><option value="estabelecimento" ${p.kind==='estabelecimento'?'selected':''}>Estabelecimento</option><option value="produto" ${p.kind==='produto'?'selected':''}>Produto</option></select><button class="btn btn-sm btn-g btn-dl" data-act="rmPend" data-i="${i}">${ic('trash','s')} Remover</button></div></div>`).join('')}</div></div>`:''}
 ${g.length?`<p class="xs muted" style="margin:14px 0 0">Arraste para reordenar (ou use as setas). A foto marcada como principal aparece primeiro.</p><div class="gal" id="galGrid">${g.map((x,i)=>`<div class="gi ${i===0?'main':''}" draggable="true" data-gi="${i}">${i===0?'<span class="chip chip-or mt">Principal</span>':''}<img src="${esc(safeImg(x.url))}" alt="${esc(x.caption||'Foto '+(i+1))}"><div class="gb"><input value="${esc(x.caption||'')}" placeholder="Legenda" data-cap="${i}" aria-label="Legenda da foto ${i+1}"><div class="ga"><button data-act="gMove" data-i="${i}" data-d="-1" aria-label="Mover para trás" ${i===0?'disabled':''}>${ic('left','s')}</button><button data-act="gMove" data-i="${i}" data-d="1" aria-label="Mover para frente" ${i===g.length-1?'disabled':''}>${ic('right','s')}</button><button data-act="gMain" data-i="${i}" title="Definir como principal" aria-label="Definir como principal">${ic('star','s')}</button><label title="Substituir" style="border:1px solid var(--line);border-radius:8px;padding:5px 7px;cursor:pointer;display:grid;place-items:center">${ic('upload','s')}<input type="file" class="sr" accept="image/jpeg,image/png,image/webp" data-repl="${i}" aria-label="Substituir foto"></label><button data-act="gDel" data-i="${i}" aria-label="Excluir foto">${ic('trash','s')}</button></div></div></div>`).join('')}</div>`:S.pend.length?'':`<p class="sm muted" style="margin-top:12px">Nenhuma foto publicada ainda.</p>`}`}
function rerenderGal(){const c=curCompany();const box=$('#galBox');if(box){box.innerHTML=galleryBlock(c);bindGallery()}else render(false)}
function addPend(files){const c=curCompany();const g=rawC(c.id)?.gallery||[];const lim=planById(c.plan).photos||5;let n=0;for(const f of files){if(!/^image\/(jpeg|png|webp)$/.test(f.type)){toast(`${f.name}: formato não suportado.`,'err');continue}if(f.size>10*1024*1024){toast(`${f.name}: acima de 10 MB.`,'err');continue}if(g.length+S.pend.length>=lim){toast(`Limite de ${lim} fotos do seu plano atingido.`,'err');break}S.pend.push({file:f,url:URL.createObjectURL(f),caption:'',kind:'estabelecimento'});n++}if(n)rerenderGal()}
function bindGallery(){const dz=$('#dropZone');if(!dz)return;const inp=$('#galInput');inp.onchange=()=>{addPend([...inp.files]);inp.value=''};dz.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();inp.click()}};['dragenter','dragover'].forEach(ev=>dz.addEventListener(ev,e=>{e.preventDefault();dz.classList.add('over')}));['dragleave','drop'].forEach(ev=>dz.addEventListener(ev,e=>{e.preventDefault();dz.classList.remove('over')}));dz.addEventListener('drop',e=>addPend([...e.dataTransfer.files]));
 $$('[data-pc]').forEach(i=>i.oninput=()=>S.pend[+i.dataset.pc].caption=i.value);$$('[data-pk]').forEach(i=>i.onchange=()=>S.pend[+i.dataset.pk].kind=i.value);
 $$('[data-cap]').forEach(i=>i.onchange=()=>{const idx=+i.dataset.cap;W(saveC(curCompany().id,c=>{if(c.gallery?.[idx])c.gallery[idx].caption=i.value.slice(0,140)}),'Legenda salva.')});
 $$('[data-repl]').forEach(i=>i.onchange=async()=>{const f=i.files[0];if(!f)return;const idx=+i.dataset.repl;const c=curCompany();try{toast('Substituindo…');const img=await uploadImage(f,{max:1800,q:.8});const old=rawC(c.id).gallery[idx];if(await W(saveC(c.id,x=>{x.gallery[idx]={...x.gallery[idx],...img}}),'Foto substituída.')){deleteAsset(old);rerenderGal()}}catch(e){toast(e.message,'err')}});
 let from=null;$$('#galGrid .gi').forEach(el=>{el.addEventListener('dragstart',()=>{from=+el.dataset.gi;el.classList.add('dragging')});el.addEventListener('dragend',()=>el.classList.remove('dragging'));el.addEventListener('dragover',e=>e.preventDefault());el.addEventListener('drop',e=>{e.preventDefault();const to=+el.dataset.gi;if(from==null||from===to)return;moveImg(from,to);from=null})})}
async function moveImg(from,to){const c=curCompany();if(await W(saveC(c.id,x=>{const g=x.gallery||[];const[it]=g.splice(from,1);g.splice(to,0,it);x.gallery=g})))rerenderGal()}
ACT.pickImgs=(a,e)=>{if(e.target.closest('input'))return;$('#galInput').click()};
ACT.rmPend=a=>{const[p]=S.pend.splice(+a.dataset.i,1);URL.revokeObjectURL(p.url);rerenderGal()};
ACT.clearPend=()=>{S.pend.forEach(p=>URL.revokeObjectURL(p.url));S.pend=[];rerenderGal()};
ACT.pubPend=async a=>{const c=curCompany();a.disabled=true;const done=[];try{for(let i=0;i<S.pend.length;i++){a.textContent=`Enviando ${i+1} de ${S.pend.length}…`;const p=S.pend[i];const img=await uploadImage(p.file,{max:1800,q:.8});done.push({...img,caption:p.caption.slice(0,140),kind:p.kind})}}catch(e){toast(e.message,'err')}if(done.length&&await W(saveC(c.id,x=>{x.gallery=[...(x.gallery||[]),...done]}),`${done.length} foto${done.length>1?'s':''} publicada${done.length>1?'s':''}.`)){S.pend.forEach(p=>URL.revokeObjectURL(p.url));S.pend=S.pend.slice(done.length)}rerenderGal()};
ACT.gMove=a=>{const i=+a.dataset.i,d=+a.dataset.d;moveImg(i,i+d)};
ACT.gMain=a=>{const i=+a.dataset.i;if(i>0)moveImg(i,0)};
ACT.gDel=async a=>{const i=+a.dataset.i;if(!await confirmBox('Excluir esta foto da galeria? Esta ação não pode ser desfeita.',{ok:'Excluir',danger:true}))return;const c=curCompany();const old=rawC(c.id).gallery[i];if(await W(saveC(c.id,x=>{x.gallery.splice(i,1)}),'Foto excluída.')){deleteAsset(old);rerenderGal()}};
V['painel-fotos']=pv('painel-fotos',{title:'Fotos e galeria',live:false,render(){const c=curCompany();if(!c)return noCompany();return`<div class="dhead"><div><h1>Fotos e galeria</h1><p>Mostre o seu espaço, seus produtos e sua equipe. Fotos boas aumentam os contatos.</p></div></div><div class="card"><div id="galBox">${galleryBlock(c)}</div></div>`},after(){bindGallery()}});

/* ---------- produtos e serviços ---------- */
V['painel-produtos']=pv('painel-produtos',{title:'Produtos e serviços',render(){const c=curCompany();if(!c)return noCompany();const p=rawC(c.id)?.products||[];return`<div class="dhead"><div><h1>Produtos e serviços</h1><p>Eles aparecem na sua página e na busca do portal.</p></div><button class="btn btn-p" data-act="prodForm">${ic('plus','s')} Adicionar</button></div>${p.length?`<div class="list">${p.map((x,i)=>`<div class="li">${safeImg(x.image?.url)?`<img src="${esc(safeImg(x.image.url))}" alt="" style="width:56px;height:56px;border-radius:12px;object-fit:cover">`:`<div class="ico">${ic(x.kind==='servico'?'brief':'box')}</div>`}<div class="grow"><b>${esc(x.name)}</b><div class="sm muted">${x.kind==='servico'?'Serviço':'Produto'}${num(x.price)?' · '+money(num(x.price)):''}</div></div><button class="btn btn-sm" data-act="prodForm" data-i="${i}">${ic('edit','s')} Editar</button><button class="btn btn-sm btn-g btn-dl" data-act="prodDel" data-i="${i}" aria-label="Excluir">${ic('trash','s')}</button></div>`).join('')}</div>`:empty('Nenhum produto ou serviço cadastrado.','Adicione o que você vende ou os serviços que presta.')}`}});
ACT.prodForm=a=>{const c=curCompany();const i=a.dataset.i;const x=i!=null?(rawC(c.id).products||[])[+i]:{};modal(`<h3>${i!=null?'Editar':'Adicionar'} produto ou serviço</h3><form data-form="prod" data-i="${i??''}"><div class="fld"><label for="pfN">Nome *</label><input id="pfN" type="text" name="name" value="${esc(x.name||'')}" required maxlength="80"></div><div class="fgrid"><div class="fld"><label for="pfK">Tipo</label><select id="pfK" name="kind"><option value="produto">Produto</option><option value="servico" ${x.kind==='servico'?'selected':''}>Serviço</option></select></div><div class="fld"><label for="pfP">Preço (R$)</label><input id="pfP" type="text" inputmode="decimal" name="price" value="${esc(x.price??'')}" placeholder="Opcional"></div></div><div class="fld"><label for="pfD">Descrição</label><textarea id="pfD" name="desc" maxlength="400">${esc(x.desc||'')}</textarea></div><div class="fld"><label for="pfI">Imagem</label><input id="pfI" type="file" name="img" accept="image/jpeg,image/png,image/webp"></div><div class="mact"><button type="button" class="btn" data-act="mNo">Cancelar</button><button class="btn btn-p">Salvar</button></div></form>`)};
FORM.prod=async(f,o)=>{if(!o.name)return toast('Informe o nome.','err');if(o.price&&num(o.price)==null)return toast('Preço inválido.','err');const c=curCompany();const i=f.dataset.i;let img;const file=f.querySelector('[name=img]').files[0];if(file){try{img=await uploadImage(file,{max:900,q:.8})}catch(e){return toast(e.message,'err')}}const item={id:genId(),name:o.name,kind:o.kind,price:o.price?num(o.price):null,desc:o.desc};if(await W(saveC(c.id,x=>{x.products=x.products||[];if(i!==''){const old=x.products[+i];x.products[+i]={...old,...item,id:old.id||item.id,image:img||old.image}}else x.products.push({...item,image:img||null})}),'Salvo.')){closeModal();render(false)}};
ACT.prodDel=async a=>{if(!await confirmBox('Excluir este item?',{ok:'Excluir',danger:true}))return;const c=curCompany();const old=rawC(c.id).products[+a.dataset.i];if(await W(saveC(c.id,x=>{x.products.splice(+a.dataset.i,1)}),'Item excluído.')){deleteAsset(old?.image);render(false)}};

/* ---------- promoções ---------- */
V['painel-promocoes']=pv('painel-promocoes',{title:'Promoções',render(){const c=curCompany();if(!c)return noCompany();const all=allPromos().filter(p=>p.companyId===c.id).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));const tab=S.ptab||'ativas';const groups={ativas:all.filter(p=>['ativa','agendada','aguardando'].includes(p.status)),rascunhos:all.filter(p=>p.status==='rascunho'),historico:all.filter(p=>['encerrada','rejeitada'].includes(p.status))};const plan=planById(c.plan);const list=groups[tab];
 return`<div class="dhead"><div><h1>Promoções e ofertas</h1><p>Seu plano permite ${nf(plan.promos||0)} promoç${plan.promos===1?'ão':'ões'} ao mesmo tempo. Vencidas saem do ar automaticamente.</p></div><button class="btn btn-p" data-act="newPromo">${ic('plus','s')} Criar promoção</button></div>${!c.pub?`<div class="note or" style="margin-bottom:14px">${ic('alert')} Promoções só aparecem no portal depois que a empresa for aprovada.</div>`:''}<div class="tabs">${[['ativas','Ativas e agendadas'],['rascunhos','Rascunhos'],['historico','Histórico']].map(([k,l])=>`<a href="#painel-promocoes" data-act="ptab" data-v="${k}" class="${tab===k?'on':''}">${l} (${groups[k].length})</a>`).join('')}</div>
 ${list.length?`<div class="list">${list.map(p=>`<div class="li" style="align-items:flex-start"><div class="ico" style="background:#fdf0e3;color:#b25f17">${ic('tag')}</div><div class="grow"><div class="row"><b>${esc(p.title)}</b>${statusChip(PSTATUS,p.status)}${discount(p)?`<span class="chip chip-or">-${discount(p)}%</span>`:''}</div><div class="sm muted">${esc(PROMO_TYPES[p.type]||'')} · ${p.start?fmtD(p.start):'—'} a ${p.end?fmtD(p.end):'—'}${num(p.priceTo)?' · '+money(num(p.priceTo)):''}</div>${p.status==='rejeitada'&&p.m?.reason?`<div class="note rd" style="margin-top:6px">${ic('alert','s')} ${esc(p.m.reason)}</div>`:''}</div><div class="row">${['encerrada'].includes(p.status)?'':`<button class="btn btn-sm" data-act="newPromo" data-id="${esc(p.id)}">${ic('edit','s')} Editar</button>`}<button class="btn btn-sm" data-act="dupPromo" data-id="${esc(p.id)}" title="Duplicar">${ic('copy','s')}</button>${['ativa','agendada'].includes(p.status)?`<button class="btn btn-sm btn-dl" data-act="endPromo" data-id="${esc(p.id)}">Encerrar</button>`:''}${p.status==='rascunho'?`<button class="btn btn-sm btn-g btn-dl" data-act="delPromo" data-id="${esc(p.id)}" aria-label="Excluir">${ic('trash','s')}</button>`:''}</div></div>`).join('')}</div>`:empty(tab==='ativas'?'Nenhuma promoção ativa.':tab==='rascunhos'?'Nenhum rascunho.':'Sem histórico ainda.','',tab==='ativas'?`<button class="btn btn-p" data-act="newPromo">Criar promoção</button>`:'')}`}});
ACT.ptab=a=>{S.ptab=a.dataset.v;render(false)};
ACT.newPromo=a=>{const c=curCompany();if(!c)return go('painel-nova');const id=a.dataset.id;const p=id?(S.owners[S.uid]?.promos?.[id]||{}):{start:dayKey(),type:'percentual'};const prods=rawC(c.id)?.products||[];modal(`<h3>${id?'Editar promoção':'Nova promoção'}</h3><form data-form="promo" data-id="${esc(id||'')}" novalidate><div class="fgrid"><div class="fld full"><label for="prT">Título da promoção *</label><input id="prT" type="text" name="title" value="${esc(p.title||'')}" required maxlength="90"></div><div class="fld"><label for="prTy">Tipo *</label><select id="prTy" name="type">${Object.entries(PROMO_TYPES).map(([k,l])=>`<option value="${k}" ${p.type===k?'selected':''}>${l}</option>`).join('')}</select></div><div class="fld"><label for="prPr">Produto ou serviço relacionado</label><select id="prPr" name="product"><option value="">Nenhum</option>${prods.map(x=>`<option value="${esc(x.id)}" ${p.product===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="fld full"><label for="prD">Descrição</label><textarea id="prD" name="desc" maxlength="600">${esc(p.desc||'')}</textarea></div><div class="fld"><label for="prF">Preço original (R$)</label><input id="prF" type="text" inputmode="decimal" name="priceFrom" value="${esc(p.priceFrom??'')}"></div><div class="fld"><label for="prTo">Preço promocional (R$)</label><input id="prTo" type="text" inputmode="decimal" name="priceTo" value="${esc(p.priceTo??'')}"></div><div class="fld"><label for="prPct">Percentual de desconto</label><input id="prPct" type="text" inputmode="decimal" name="pct" value="${esc(p.pct??'')}" placeholder="Calculado automaticamente"><span class="hint" id="pctHint"></span></div><div class="fld"><label for="prQ">Quantidade disponível</label><input id="prQ" type="number" min="0" name="qty" value="${esc(p.qty??'')}" placeholder="Opcional"></div><div class="fld"><label for="prS">Data de início *</label><input id="prS" type="date" name="start" value="${esc(p.start||'')}" required></div><div class="fld"><label for="prE">Data de encerramento *</label><input id="prE" type="date" name="end" value="${esc(p.end||'')}" required></div><div class="fld"><label for="prC">Código promocional</label><input id="prC" type="text" name="code" value="${esc(p.code||'')}" maxlength="30" placeholder="Opcional"></div><div class="fld"><label for="prW">WhatsApp para contato</label><input id="prW" type="tel" name="whatsapp" value="${esc(p.whatsapp||'')}" data-mask="phone" placeholder="Usa o da empresa se vazio"></div><div class="fld full"><label for="prTe">Termos e condições</label><textarea id="prTe" name="terms" maxlength="800" style="min-height:70px">${esc(p.terms||'')}</textarea></div><div class="fld full"><label for="prI">Imagem promocional</label>${safeImg(p.image?.url)?`<img src="${esc(safeImg(p.image.url))}" alt="" style="max-height:90px;border-radius:10px;margin-bottom:6px">`:''}<input id="prI" type="file" name="img" accept="image/jpeg,image/png,image/webp"></div></div>${p.submittedAt?'<p class="xs muted">Editar uma promoção publicada envia a nova versão para aprovação.</p>':''}<div class="mact"><button type="button" class="btn" data-act="mNo">Cancelar</button><button class="btn" name="mode" value="draft" data-act="promoDraft">Salvar rascunho</button><button class="btn btn-p">Publicar promoção</button></div></form>`,{wide:true});const upd=()=>{const a=num($('#prF').value),b=num($('#prTo').value);$('#pctHint').textContent=a&&b&&a>b?`Desconto calculado: ${Math.round((1-b/a)*100)}%`:''};$('#prF').oninput=upd;$('#prTo').oninput=upd;upd()};
ACT.promoDraft=a=>{const f=a.closest('form');f.dataset.draft='1';f.requestSubmit()};
FORM.promo=async(f,o)=>{const draft=f.dataset.draft==='1';f.dataset.draft='';clearErr(f);const c=curCompany();const id=f.dataset.id||genId();let bad=false;if(!o.title){fieldErr(f,'title','Informe o título.');bad=true}const a=num(o.priceFrom),b=num(o.priceTo);if(o.priceFrom&&a==null){fieldErr(f,'priceFrom','Valor inválido.');bad=true}if(o.priceTo&&b==null){fieldErr(f,'priceTo','Valor inválido.');bad=true}if(a&&b&&b>=a){fieldErr(f,'priceTo','O preço promocional deve ser menor que o original.');bad=true}if(!draft){if(!o.start){fieldErr(f,'start','Informe a data de início.');bad=true}if(!o.end){fieldErr(f,'end','Informe a data de encerramento.');bad=true}if(o.start&&o.end&&o.end<o.start){fieldErr(f,'end','O encerramento deve ser após o início.');bad=true}if(o.end&&o.end<dayKey()){fieldErr(f,'end','A data de encerramento já passou.');bad=true}}if(bad)return;
 if(!draft){const plan=planById(c.plan);const busy=allPromos().filter(p=>p.companyId===c.id&&p.id!==id&&['ativa','agendada','aguardando'].includes(p.status)).length;if(busy>=(plan.promos||0)){toast(`Seu plano ${plan.name} permite ${plan.promos||0} promoç${plan.promos===1?'ão':'ões'} simultânea${plan.promos===1?'':'s'}. Encerre uma ou mude de plano.`,'err');return}if(userBlocked(S.uid))return toast('Conta bloqueada.','err')}
 let img;const file=f.querySelector('[name=img]').files[0];if(file){try{img=await uploadImage(file,{max:1400,q:.8})}catch(e){return toast(e.message,'err')}}
 if(await W(mutateMy(bd=>{bd.promos=bd.promos||{};const old=bd.promos[id]||{createdAt:now()};bd.promos[id]={...old,companyId:c.id,title:o.title,type:o.type,product:o.product,desc:o.desc,priceFrom:a,priceTo:b,pct:o.pct?num(o.pct):(a&&b&&a>b?Math.round((1-b/a)*100):null),qty:o.qty===''?null:+o.qty,start:o.start,end:o.end,code:o.code,whatsapp:o.whatsapp,terms:o.terms,image:img||old.image||null,updatedAt:now(),submittedAt:draft?(old.submittedAt||null):now(),endedAt:null}}),draft?'Rascunho salvo.':site().autoApprovePromos?'Promoção publicada!':'Promoção enviada para aprovação.')){closeModal();S.ptab=draft?'rascunhos':'ativas';if(S.route.n==='painel-promocoes')render(false);else go('painel-promocoes')}};
ACT.dupPromo=async a=>{const p=S.owners[S.uid].promos[a.dataset.id];const id=genId();if(await W(mutateMy(b=>{b.promos[id]={...clone(p),title:p.title+' (cópia)',submittedAt:null,endedAt:null,createdAt:now(),updatedAt:now()}}),'Promoção duplicada como rascunho.')){S.ptab='rascunhos';render(false)}};
ACT.endPromo=async a=>{if(!await confirmBox('Encerrar esta promoção agora? Ela sai do portal e fica no seu histórico.',{ok:'Encerrar',danger:true}))return;if(await W(mutateMy(b=>{b.promos[a.dataset.id].endedAt=now()}),'Promoção encerrada.'))render(false)};
ACT.delPromo=async a=>{if(!await confirmBox('Excluir este rascunho?',{ok:'Excluir',danger:true}))return;const old=S.owners[S.uid].promos[a.dataset.id];if(await W(mutateMy(b=>{delete b.promos[a.dataset.id]}),'Rascunho excluído.')){deleteAsset(old?.image);render(false)}};

/* ---------- avaliações ---------- */
V['painel-avaliacoes']=pv('painel-avaliacoes',{title:'Avaliações',live:false,render(){const c=curCompany();if(!c)return noCompany();const rv=reviewsFor(c.id);const r=ratingOf(c.id);const rep=rawC(c.id)?.replies||{};return`<div class="dhead"><div><h1>Avaliações</h1><p>${r?`Nota média ${r.avg.toFixed(1).replace('.',',')} em ${r.n} avaliação${r.n>1?'ões':''}.`:'Sua empresa ainda não recebeu avaliações.'}</p></div></div>${rv.length?`<div class="list">${rv.map(x=>`<div class="card" style="margin:0"><div class="row between"><b data-uname="${esc(x.uid)}">Usuário do portal</b><span class="stars">${'★'.repeat(+x.rating)}<span class="muted">${'★'.repeat(5-x.rating)}</span></span></div><p class="sm" style="margin:6px 0">${esc(x.text||'(sem comentário)')}</p><div class="xs muted">${fmtD(x.at)}</div><form data-form="reply" data-u="${esc(x.uid)}" class="row" style="margin-top:10px"><input class="inp grow" name="text" value="${esc(rep[x.uid]?.text||'')}" placeholder="Responder publicamente" aria-label="Resposta" maxlength="400"><button class="btn btn-sm btn-b">${rep[x.uid]?'Atualizar':'Responder'}</button></form></div>`).join('')}</div>`:empty('Sem avaliações por enquanto.','Peça aos seus clientes para avaliarem sua página no portal.')}`}});
FORM.reply=async(f,o)=>{const c=curCompany();const u=f.dataset.u;if(await W(saveC(c.id,x=>{x.replies=x.replies||{};if(o.text)x.replies[u]={text:o.text,at:now()};else delete x.replies[u]}),'Resposta salva.'))render(false)};

/* ---------- estatísticas ---------- */
V['painel-estatisticas']=pv('painel-estatisticas',{title:'Estatísticas',render(){const c=curCompany();if(!c)return noCompany();const plan=planById(c.plan);const{tot,byDay}=statsFor(c.id);const days=[...Array(30)].map((_,i)=>{const d=new Date();d.setDate(d.getDate()-29+i);return dayKey(d)});const mx=Math.max(1,...days.map(d=>byDay[d]?.v||0));const clicks=tot.w+tot.p+tot.r+tot.s+tot.l;
 return`<div class="dhead"><div><h1>Estatísticas</h1><p>Dados reais registrados no portal desde a publicação.</p></div></div><div class="kpis">${[['eye','Visualizações',tot.v],['wa','WhatsApp',tot.w],['phone','Telefone',tot.p],['route','Como chegar',tot.r],['share','Compartilhamentos',tot.s],['globe','Redes e site',tot.l]].map(([i,l,v])=>`<div class="kpi"><span>${ic(i,'s')}${l}</span><b>${nf(v)}</b></div>`).join('')}</div>
 ${plan.reports?`<div class="card"><h3>Visualizações nos últimos 30 dias</h3><div class="bars" role="img" aria-label="Gráfico de visualizações diárias">${days.map(d=>`<div style="height:${((byDay[d]?.v||0)/mx*100).toFixed(1)}%" title="${fmtD(d)}: ${byDay[d]?.v||0} visualizações"></div>`).join('')}</div><div class="row between xs muted"><span>${fmtD(days[0])}</span><span>${fmtD(days[29])}</span></div></div>`:`<div class="note or">${ic('chart')} <span>Relatórios diários estão disponíveis nos planos Destaque e Premium. <a href="#painel-plano">Ver planos</a></span></div>`}
 ${plan.advanced?`<div class="card"><h3>Análise de contatos</h3><div class="hbars">${[['WhatsApp',tot.w],['Telefone',tot.p],['Como chegar',tot.r],['Compartilhar',tot.s],['Redes e site',tot.l]].map(([l,v])=>`<div class="hb"><span class="sm">${l}</span><i style="width:${clicks?(v/clicks*100):0}%"></i><b class="sm">${nf(v)}</b></div>`).join('')}</div><p class="sm" style="margin-top:12px">Taxa de conversão (contatos ÷ visualizações): <b>${tot.v?((tot.w+tot.p+tot.r)/tot.v*100).toFixed(1).replace('.',','):'0'}%</b></p></div>`:plan.reports?`<div class="note" style="margin-top:14px">${ic('chart')} Estatísticas avançadas (conversão por canal) fazem parte do plano Premium.</div>`:''}`}});

/* ---------- eventos e vagas da empresa ---------- */
function ownerList(kind,prefix,c){return ownerItems(kind,prefix).filter(x=>x.ownerId===S.uid&&x.companyId===c.id)}
const ISTAT={rascunho:['Rascunho','chip-gy'],pendente:['Aguardando aprovação','chip-or'],aprovado:['Publicado','chip-gn'],rejeitado:['Rejeitado','chip-rd']};
V['painel-eventos']=pv('painel-eventos',{title:'Eventos',render(){const c=curCompany();if(!c)return noCompany();const plan=planById(c.plan);const list=ownerList('events','e_',c);return`<div class="dhead"><div><h1>Eventos da empresa</h1><p>Divulgue eventos próprios na agenda da cidade. Todos passam por moderação.</p></div>${plan.events&&c.pub?`<button class="btn btn-p" data-act="evForm">${ic('plus','s')} Novo evento</button>`:''}</div>${!plan.events?`<div class="note or">${ic('alert')} <span>A divulgação de eventos faz parte do plano Premium. <a href="#painel-plano">Ver planos</a></span></div>`:!c.pub?`<div class="note or">${ic('alert')} Disponível após a aprovação da empresa.</div>`:''}${list.length?`<div class="list" style="margin-top:14px">${list.map(e=>`<div class="li"><div class="ico">${ic('cal')}</div><div class="grow"><b>${esc(e.title)}</b><div class="sm muted">${fmtD(e.date)} · ${esc(e.place||'')}</div>${e.status==='rejeitado'&&S.mod['e_'+e.id]?.reason?`<div class="xs" style="color:#9a2f1a">${esc(S.mod['e_'+e.id].reason)}</div>`:''}</div>${statusChip(ISTAT,e.status)}<button class="btn btn-sm" data-act="evForm" data-id="${esc(e.id)}">${ic('edit','s')}</button><button class="btn btn-sm btn-g btn-dl" data-act="ownDel" data-k="events" data-id="${esc(e.id)}" aria-label="Excluir">${ic('trash','s')}</button></div>`).join('')}</div>`:''}`}});
ACT.evForm=a=>{const id=a.dataset.id;const e=id?S.owners[S.uid].events[id]:{};modal(`<h3>${id?'Editar':'Novo'} evento</h3><form data-form="ownEvent" data-id="${esc(id||'')}"><div class="fld"><label for="oeT">Título *</label><input id="oeT" type="text" name="title" value="${esc(e.title||'')}" required></div><div class="fgrid"><div class="fld"><label for="oeTy">Tipo</label><select id="oeTy" name="type">${EVENT_TYPES.map(t=>`<option ${e.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="fld"><label for="oeD">Data *</label><input id="oeD" type="date" name="date" value="${esc(e.date||'')}" required></div><div class="fld"><label for="oeH">Horário</label><input id="oeH" type="time" name="time" value="${esc(e.time||'')}"></div><div class="fld"><label for="oeE">Data final</label><input id="oeE" type="date" name="endDate" value="${esc(e.endDate||'')}"></div><div class="fld full"><label for="oeP">Local *</label><input id="oeP" type="text" name="place" value="${esc(e.place||'')}" required></div><div class="fld full"><label for="oeA">Endereço</label><input id="oeA" type="text" name="address" value="${esc(e.address||'')}"></div></div><div class="fld"><label for="oeDs">Descrição</label><textarea id="oeDs" name="description">${esc(e.description||'')}</textarea></div><div class="fld"><label for="oeL">Link externo</label><input id="oeL" type="url" name="link" value="${esc(e.link||'')}"></div><div class="fld"><label for="oeI">Imagem</label><input id="oeI" type="file" name="img" accept="image/jpeg,image/png,image/webp"></div><div class="mact"><button type="button" class="btn" data-act="mNo">Cancelar</button><button class="btn btn-p">Enviar para aprovação</button></div></form>`,{wide:true})};
FORM.ownEvent=async(f,o)=>{if(!o.title||!o.date||!o.place)return toast('Preencha título, data e local.','err');const c=curCompany();const id=f.dataset.id||genId();let img;const file=f.querySelector('[name=img]').files[0];if(file){try{img=await uploadImage(file,{max:1400})}catch(e){return toast(e.message,'err')}}if(await W(mutateMy(b=>{b.events=b.events||{};const old=b.events[id]||{createdAt:now()};b.events[id]={...old,...o,link:o.link?safeUrl(o.link):'',companyId:c.id,image:img||old.image||null,submittedAt:now()}}),'Evento enviado para aprovação.')){closeModal();render(false)}};
V['painel-vagas']=pv('painel-vagas',{title:'Vagas',render(){const c=curCompany();if(!c)return noCompany();const list=ownerList('jobs','j_',c);return`<div class="dhead"><div><h1>Vagas de emprego</h1><p>Publique vagas da sua empresa. Elas passam por moderação antes de aparecer.</p></div>${c.pub?`<button class="btn btn-p" data-act="jobForm">${ic('plus','s')} Nova vaga</button>`:''}</div>${!c.pub?`<div class="note or">${ic('alert')} Disponível após a aprovação da empresa.</div>`:''}${list.length?`<div class="list" style="margin-top:14px">${list.map(j=>`<div class="li"><div class="ico">${ic('brief')}</div><div class="grow"><b>${esc(j.title)}</b><div class="sm muted">${esc(j.contract||'')} · ${esc(j.mode||'')}${j.deadline?' · até '+fmtD(j.deadline):''}</div></div>${statusChip(ISTAT,j.status)}<button class="btn btn-sm" data-act="jobForm" data-id="${esc(j.id)}">${ic('edit','s')}</button><button class="btn btn-sm btn-g btn-dl" data-act="ownDel" data-k="jobs" data-id="${esc(j.id)}" aria-label="Excluir">${ic('trash','s')}</button></div>`).join('')}</div>`:c.pub?empty('Nenhuma vaga publicada.'):''}`}});
const JOB_MODES=['Presencial','Remoto','Híbrido'],JOB_CONTRACTS=['CLT','PJ','Estágio','Temporário','Freelancer','Jovem aprendiz'];
ACT.jobForm=a=>{const id=a.dataset.id;const j=id?S.owners[S.uid].jobs[id]:{};modal(`<h3>${id?'Editar':'Nova'} vaga</h3><form data-form="ownJob" data-id="${esc(id||'')}"><div class="fld"><label for="ojT">Cargo *</label><input id="ojT" type="text" name="title" value="${esc(j.title||'')}" required></div><div class="fld"><label for="ojD">Descrição *</label><textarea id="ojD" name="description" required>${esc(j.description||'')}</textarea></div><div class="fld"><label for="ojR">Requisitos</label><textarea id="ojR" name="requirements" style="min-height:70px">${esc(j.requirements||'')}</textarea></div><div class="fgrid"><div class="fld"><label for="ojL">Localização</label><input id="ojL" type="text" name="location" value="${esc(j.location||'')}"></div><div class="fld"><label for="ojM">Modalidade</label><select id="ojM" name="mode">${JOB_MODES.map(x=>`<option ${j.mode===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="fld"><label for="ojC">Tipo de contratação</label><select id="ojC" name="contract">${JOB_CONTRACTS.map(x=>`<option ${j.contract===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="fld"><label for="ojDl">Prazo de inscrição</label><input id="ojDl" type="date" name="deadline" value="${esc(j.deadline||'')}"></div></div><div class="fld"><label for="ojA">Forma de candidatura *</label><input id="ojA" type="text" name="apply" value="${esc(j.apply||'')}" required placeholder="Ex.: enviar currículo para vagas@empresa.com"></div><div class="mact"><button type="button" class="btn" data-act="mNo">Cancelar</button><button class="btn btn-p">Enviar para aprovação</button></div></form>`,{wide:true})};
FORM.ownJob=async(f,o)=>{if(!o.title||!o.description||!o.apply)return toast('Preencha cargo, descrição e forma de candidatura.','err');const c=curCompany();const id=f.dataset.id||genId();if(await W(mutateMy(b=>{b.jobs=b.jobs||{};const old=b.jobs[id]||{createdAt:now()};b.jobs[id]={...old,...o,companyId:c.id,submittedAt:now()}}),'Vaga enviada para aprovação.')){closeModal();render(false)}};
ACT.ownDel=async a=>{if(!await confirmBox('Excluir este item?',{ok:'Excluir',danger:true}))return;if(await W(mutateMy(b=>{delete b[a.dataset.k][a.dataset.id]}),'Excluído.'))render(false)};

/* ---------- plano ---------- */
V['painel-plano']=pv('painel-plano',{title:'Meu plano',render(){const c=curCompany();if(!c)return noCompany();const cur=planById(c.plan);const req=rawC(c.id)?.planRequest;const pend=req&&req.at>(c.m?.planHandledAt||0);return`<div class="dhead"><div><h1>Meu plano</h1><p>Plano atual: <b>${esc(cur.name)}</b>${c.m?.planSince?` desde ${fmtD(c.m.planSince)}`:''}.</p></div></div>${pend?`<div class="note" style="margin-bottom:16px">${ic('clock')} Solicitação de mudança para o plano <b>${esc(planById(req.plan).name)}</b> enviada em ${fmtD(req.at)}. A administração entrará em contato.</div>`:''}<div class="grid g3">${plans().map(p=>`<div class="card" style="${p.id===cur.id?'border:2px solid var(--az)':''}"><h3>${esc(p.name)}</h3><p style="font-family:Montserrat;font-weight:800;font-size:22px;margin:0 0 10px">${esc(p.priceText||'Sob consulta')}</p><ul style="padding-left:18px">${planBenefits(p).map(b=>`<li class="sm">${esc(b)}</li>`).join('')}</ul>${p.id===cur.id?'<span class="chip chip-gn">Plano atual</span>':`<button class="btn btn-b btn-sm" data-act="reqPlan" data-p="${esc(p.id)}" ${pend&&req.plan===p.id?'disabled':''}>Solicitar este plano</button>`}</div>`).join('')}</div><div class="note or" style="margin-top:16px">${ic('dollar')} <span>Cobrança online por assinatura será integrada futuramente. Por enquanto, nenhum pagamento é feito por aqui: a administração ativa o plano após combinar o pagamento com você.</span></div>`}});
ACT.reqPlan=async a=>{const c=curCompany();const p=planById(a.dataset.p);if(!await confirmBox(`Solicitar a mudança para o plano ${p.name}? A administração vai analisar e entrar em contato.`,{ok:'Solicitar'}))return;if(await W(saveC(c.id,x=>{x.planRequest={plan:p.id,at:now()}}),'Solicitação enviada.'))render(false)};

/* ---------- configurações ---------- */
V['painel-config']=pv('painel-config',{title:'Configurações da conta',render(){const me=S.me||{};const mine=myCompanies();return`<div class="dhead"><div><h1>Configurações da conta</h1></div></div><div class="card"><h3>Dados do responsável</h3><p class="sm">${esc(me.name||'')} · ${esc(me.email||'')} · ${esc(me.phone||'')}${me.whatsapp?' · WhatsApp '+esc(me.whatsapp):''}</p><a class="btn btn-sm" href="#cadastro">${ic('edit','s')} Editar dados</a></div><div class="card"><h3>Minhas empresas</h3><p class="sm muted">Uma conta pode administrar várias empresas. Alterne entre elas pelo seletor do menu.</p><div class="list">${mine.map(c=>`<div class="li">${logoEl(c,'avatar')}<div class="grow"><b>${esc(c.name||'Sem nome')}</b><div class="xs">${statusChip(CSTATUS,c.status)}</div></div><button class="btn btn-sm" data-act="useC" data-id="${esc(c.id)}">Gerenciar</button><button class="btn btn-sm btn-g btn-dl" data-act="delC" data-id="${esc(c.id)}" aria-label="Excluir empresa">${ic('trash','s')}</button></div>`).join('')||'<p class="sm muted">Nenhuma empresa.</p>'}</div><a class="btn btn-sm" style="margin-top:12px" href="#painel-nova">${ic('plus','s')} Cadastrar outra empresa</a></div><div class="card"><h3>Privacidade (LGPD)</h3><p class="sm">Você pode excluir definitivamente sua conta de empresário: dados pessoais, empresas, promoções, avaliações e registros de uso vinculados a você.</p><button class="btn btn-sm btn-dl" data-act="wipeMe">${ic('trash','s')} Excluir todos os meus dados</button></div>`}});
ACT.useC=a=>{S.curCid=a.dataset.id;try{localStorage.setItem('pc_cid',S.curCid)}catch(e){}go('painel')};
ACT.delC=async a=>{const id=a.dataset.id;const c=compById(id);if(!await confirmBox(`Excluir “${c?.name}” e todas as suas promoções, eventos e vagas? Esta ação não pode ser desfeita.`,{ok:'Excluir empresa',danger:true}))return;const raw=rawC(id)||{};if(await W(mutateMy(b=>{delete b.companies[id];for(const k of['promos','events','jobs'])for(const[x,v]of Object.entries(b[k]||{}))if(v.companyId===id)delete b[k][x]}),'Empresa excluída.')){[raw.logo,raw.cover,...(raw.gallery||[])].forEach(deleteAsset);if(S.me?.docs?.[id])W(mutatePriv(b=>{delete b.docs[id]}));S.curCid=null;render(false)}};
ACT.wipeMe=async()=>{if(!await confirmBox('Excluir definitivamente todos os seus dados do portal? Suas empresas deixarão de aparecer imediatamente.',{ok:'Excluir tudo',danger:true}))return;try{for(const p of['companies/','private/','reviews/','metrics/'])await S.db.doc(p+S.uid).delete();toast('Seus dados foram excluídos.','ok');go('inicio')}catch(e){W(Promise.reject(e))}};
